/** An element of the syntax tree compile() returns. */
export interface Element {
  /** Rule, declaration or comment type, or an at-rule's name (`@media`). */
  type: string;
  /** The statement's text: a rule's selector, an at-rule's prelude, a declaration with its `;`. */
  value: string;
  /** A rule's resolved selectors or an at-rule's conditions; a declaration's property. */
  props: string[] | string;
  /** The innermost enclosing at-rule. */
  root: Element | null;
  /** The enclosing element. */
  parent: Element | null;
  /** Nested elements; a declaration's value or a comment's text. */
  children: Element[] | string;
  line: number;
  column: number;
  /** A declaration's property length; negative for elements generated by plugins. */
  length: number;
  /** The output a middleware chose for the element, if any. */
  return: string;
  /** The list the element was compiled into (lift() adds generated rules to the top-level one). */
  siblings?: Element[];
}

/** A plugin: called with each element; returns output or updates the element. */
export type Middleware = (element: Element, index: number, children: Element[], callback: Middleware) => string | void;

