/** Parses CSS with nesting into top-level elements. */
export declare function compile(css: string): Element[];
/** Serializes elements with a middleware. */
export declare function serialize(children: Element[], callback: Middleware): string;
/** The middleware that prints CSS. */
export declare function stringify(element: Element, index: number, children: Element[], callback: Middleware): string;
/** Combines middleware into one. */
export declare function middleware(collection: Middleware[]): Middleware;
/** Calls back with each top-level rule's CSS (after stringify). */
export declare function rulesheet(callback: (rule: string) => void): Middleware;
/** Adds vendor-prefixed declarations, keyframes and selectors. */
export declare function prefixer(element: Element, index: number, children: Element[], callback: Middleware): string | void;
/** Scopes nested selectors to the first; `:global(...)` escapes. */
export declare function namespace(element: Element): void;
/** Vendor-prefixed forms of a declaration (`name:value;`) followed by the declaration. */
export declare function prefix(value: string, length: number, children?: Element[]): string;
/** Splits a selector or value into names, delimited groups and single characters. */
export declare function tokenize(value: string): string[];
export declare function node(
  value: string,
  root: Element | null,
  parent: Element | null,
  type: string,
  props: string[] | string,
  children: Element[] | string,
  length: number,
  siblings?: Element[],
  line?: number,
  column?: number,
): Element;
/** A copy of an element, marked as generated, with fields replaced. */
export declare function copy(element: Element, fields: Partial<Element>): Element;
/** Adds an element, wrapped in its enclosing at-rules, to the top-level list. */
export declare function lift(element: Element): void;
export declare function strlen(value: string): number;
